-- 2026-11-04c: mp_registered_interests.first_seen_date (owner, 4 Nov 2026). The MP sync never writes this column, and it
-- had no default, so every entry added since the edition backfills has no date, and lib/member-digest.ts, which finds new
-- entries with first_seen_date >= a day, cannot see them. The table stores no published date (created_when is a later
-- date, for all 667 rows checked), so Parliament's publishedDate was read from the Interests API on 4 Nov 2026 and is
-- listed below, for 667 of the 668 rows with no date. Those rows take the earlier of that date and the day the row was
-- created. Any other row with no date (one entry the API no longer has, and any added since) takes the day the row was
-- created. New rows default to today. created_at is read in UTC, the database's own setting.
-- Undo: 2026-11-04c-mp-interests-first-seen-UNDO.sql.
-- Run: psql "$DATABASE_URL" -f scripts/migrations/2026-11-04c-mp-interests-first-seen.sql
\set ON_ERROR_STOP on
BEGIN READ WRITE;  -- explicit: the transaction pooler can hand out a connection left with a read-only default
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';
SET LOCAL TIME ZONE 'UTC';

UPDATE public.mp_registered_interests r
   SET first_seen_date = LEAST(p.published_date, r.created_at::date)
