UPDATE public.mp_registered_interests SET first_seen_date = created_at::date WHERE first_seen_date IS NULL;

ALTER TABLE public.mp_registered_interests ALTER COLUMN first_seen_date SET DEFAULT CURRENT_DATE;

DO $$
DECLARE remaining bigint;
BEGIN
  SELECT count(*) INTO remaining FROM public.mp_registered_interests WHERE first_seen_date IS NULL;
